value.Salary:
={{ (() => {
  const s = $('Scrape Jobs').item.json.salaryInsights;
  const c = s?.compensationBreakdown?.[0];

  if (!c) return 'Not disclosed';

  const currency = c.currencyCode || '';
  const min = c.minSalary;
  const max = c.maxSalary;
  const period = c.payPeriod || '';

  if (min != null && max != null) {
    return `${currency} ${min} - ${max} / ${period}`;
  }

  if (min != null) {
    return `${currency} ${min} / ${period}`;
  }

  if (max != null) {
    return `${currency} ${max} / ${period}`;
  }

  return 'Not disclosed';
})() }}
